import sys; sys.path.insert(0, '.')
import re
from phase0_v2.calibration.audit_helpers import run_pareto, measure_fix_errors
from phase0_v2.calibration._shared import load_records

records = load_records('phase0_v2/data/results/meta-llama_Llama-3.1-8B-Instruct_results.jsonl')

def strip_meta(text):
    text = re.sub(r'\(Note:.*?\)', '', text)
    text = re.sub(r'\(Translation:.*?\)', '', text)
    lines = text.split('\n')
    cleaned = [l for l in lines if not any(p in l for p in ["I'll follow", 'system instruction', "Here's the response without"])]
    return '\n'.join(cleaned)

def _vowel_ratio(text):
    vowels = set('aeiouAEIOU')
    alpha_chars = [c for c in text if c.isalpha()]
    if not alpha_chars:
        return 0.0
    return sum(1 for c in alpha_chars if c in vowels) / len(alpha_chars)

def scorer_fixed(text):
    return 1.0 - _vowel_ratio(strip_meta(text))

result = run_pareto(records, 'vowel_omission', scorer_fixed)
print(f'Pareto: threshold={result["threshold"]}, ba={result["ba"]}, d_norm={result["d_norm"]}, c_norm={result["c_norm"]}')

fix = measure_fix_errors(records, 'vowel_omission', scorer_fixed, lambda r: 1.0 - scorer_fixed(r), threshold=result['threshold'])
print(f'old: {fix["old_labels"]}')
print(f'new: {fix["new_labels"]}')
print(f'error_pct: {fix["error_pct"]:.2f}%')
print(f'changed: {fix["changed"]} labels')
